 "Live Global": "グローバル版ライブ",
 "Several sources, one site": "複数のソース、ひとつのサイト",
 "Client resources": "クライアントリソース",
 "Game tables, localized descriptions, icons and artwork extracted from an installed PC client.": "インストール済みPCクライアントから抽出したゲームテーブル、ローカライズ説明、アイコン、イラスト。",
 "Calculations": "計算",
 "Scaling, derived stats, gear scores and simulations computed from supported inputs, with their own assumptions and limits.": "対応する入力から計算した成長、派生ステータス、装備スコア、シミュレーション。それぞれ独自の前提と制限があります。",
 "Captures and imports": "キャプチャとインポート",
 "Observed profiles, equipment, counters and order history. Coverage depends on what the game sends during collection.": "観測したプロフィール、装備、カウンター、注文履歴。収集中にゲームが送る内容によって網羅範囲が変わります。",
 "Editorial content": "編集コンテンツ",
 "Readable names, explanations, artwork selections, team presets and some schedules, maintained separately from extracted game facts.": "読みやすい名称、解説、イラストの選定、チームプリセット、一部のスケジュール。抽出したゲーム情報とは別に管理しています。",
 "How each section uses the data": "各セクションのデータの使い方",
 "Shared references feed several pages. Each feature selects the relevant records and adds its own presentation or calculations.": "共有リファレンスが複数のページを支えています。各機能が関連レコードを選び、独自の表示や計算を加えます。",
