 "Datamine · modes and mechanics": "データ解析 · モードとギミック",
 "Bygone and Sequential": "BygoneとSequential",
 "Team raids": "チームレイド",
 "Items and Handbook": "アイテムとハンドブック",
 "Item records, localized text and icons form the item catalog. Handbook combines progression and equipment references into comparisons and tables.": "アイテムレコード、ローカライズテキスト、アイコンがアイテムカタログを構成します。ハンドブックは進行と装備のリファレンスを比較表にまとめています。",
 "Tools · personal data and models": "ツール · 個人データとモデル",
