 "Wish Tracker and simulator": "ガチャ履歴とシミュレーター",
 "Team and raid compositions": "チーム・レイド編成",
 "From an installed game to an update": "インストール済みゲームからアップデートまで",
 "The portable exporter runs the processing pipeline near the installed client. The website consumes its finished datasets and media.": "ポータブルエクスポーターは、インストール済みクライアントの近くで処理パイプラインを実行します。ウェブサイトは完成したデータセットとメディアを利用します。",
 "Identify the client": "クライアントを識別",
 "Read installation and launcher metadata to record the exported version and branch.": "インストールとランチャーのメタデータを読み取り、エクスポートしたバージョンとブランチを記録します。",
 "Extract selected resources": "選択したリソースを抽出",
 "UnrealExporter reads configured paths from the game archives: tables, localization and the textures needed by the site.": "UnrealExporterがゲームアーカイブから設定済みのパスを読み取ります：テーブル、ローカライズ、サイトに必要なテクスチャ。",
 "Process and connect": "処理と接続",
 "Processors resolve identifiers and join tables to translations and media. Separate curated inputs add labels, notes and preserved resources.": "プロセッサが識別子を解決し、テーブルを翻訳やメディアと結合します。別途キュレーションした入力がラベル、メモ、保持リソースを追加します。",
 "Generate the site data": "サイトデータを生成",
 "Validate and package": "検証とパッケージ化",
 "Apply and publish": "適用と公開",
 "The update is applied to the site’s generated public files and checked before deployment. Exporting a client does not itself publish the website.": "アップデートはサイトの生成済み公開ファイルに適用され、デプロイ前に確認されます。クライアントのエクスポートだけではウェブサイトは公開されません。",
 "ToF Hub Live Capture": "ToF Hub ライブキャプチャ",
 "Start before logging in": "ログイン前に開始",
 "Choose a task and follow the readiness checks. The app uses the WinDivert driver to observe network traffic and asks for Windows administrator rights.": "タスクを選び、準備チェックに従ってください。アプリはWinDivertドライバーでネットワーク通信を観測し、Windows管理者権限を求めます。",
 "Follow the in-game prompts": "ゲーム内の案内に従う",
 "Save and import": "保存とインポート",
 "Import files": "ファイルのインポート",
 "Checks and limits": "検証と制限",
 "Keep the source attached": "ソースを紐づけておく",
 "Record the source branch, export or capture time and known provenance. A test client can contain unreleased or unused records.": "元のブランチ、エクスポートまたはキャプチャの時刻、判明している出所を記録します。テストクライアントには未実装・未使用のレコードが含まれる場合があります。",
 "Check relationships and calculations": "関係と計算を確認",
 "Show uncertainty": "不確実性を示す",
 "Separate edits from observations": "編集と観測を分ける",
 "A few file terms": "ファイル用語の解説",
 "Unreal Engine archives and individual assets. Tables, configuration and textures are exported into readable formats.": "Unreal Engineのアーカイブと個別アセット。テーブル、設定、テクスチャは読みやすい形式にエクスポートされます。",
 "Localization supplies game text. JSON is the exported or generated representation used by the processors and website.": "ローカライズがゲームテキストを提供します。JSONはプロセッサとウェブサイトが使うエクスポート／生成形式です。",
 "Extracted textures are converted for display. WebP serves the site; PNG is retained for supported original-image downloads.": "抽出したテクスチャは表示用に変換されます。サイトにはWebPを使い、対応するオリジナル画像のダウンロード用にPNGを保持します。",
