 "Site": "サイト",
 "Updated the dataset to 6.4.10, added the main hub and version history, and corrected MMO data processing.": "データセットを6.4.10に更新し、メインハブとバージョン履歴を追加、MMOデータ処理を修正しました。",
 "Added the main hub with Info, Tools and Datamine shortcuts. Version branches are grouped separately; history and patcher instructions open in dialogs.": "図鑑・ツール・データ解析へのショートカットを備えたメインハブを追加。バージョンブランチは別にグループ化し、履歴とパッチャーの手順はダイアログで開きます。",
 "Feature": "機能",
 "Data": "データ",
 "Corrected MMO round and enemy references and regional season dates. Missing season floors are no longer copied from another season.": "MMOのラウンドと敵の参照、地域別シーズン日付を修正。不足しているシーズンのフロアを他のシーズンからコピーしないようにしました。",
 "Added a separate gold quality for MMO food in the pipeline, cards and rarity filter.": "MMO料理用に、パイプライン、カード、レアリティフィルターへ別枠の金品質を追加しました。",
 "Complete visual overhaul of Origin of War: progressive image loading, WebP asset optimization, responsive season cards, and deep-link affix breakdown.": "Origin of Warを全面的に刷新：段階的な画像読み込み、WebPアセット最適化、レスポンシブなシーズンカード、ディープリンク対応のアフィックス内訳。",
 "Updated Datamine data for version 6.3.0.": "データ解析データをバージョン6.3.0に更新しました。",
 "Updated Season 23 data, enemy waves, and boss values.": "シーズン23のデータ、敵ウェーブ、ボスの値を更新しました。",
 "Updated boss stages and calculated scaling values.": "ボスステージと計算済みの成長値を更新しました。",
 "Added new boss mechanics and refreshed boss cards.": "新しいボスギミックを追加し、ボスカードを更新しました。",
 "Updated Gacha and MMO item databases.": "ガチャとMMOのアイテムデータベースを更新しました。",
 "Updated Multype data from the latest full game scan.": "最新のゲーム全体スキャンからMultypeデータを更新しました。",
 "Small data and site update.": "データとサイトの軽微な更新。",
 "Added missing boss descriptions and updated the boss list.": "不足していたボス説明を追加し、ボス一覧を更新しました。",
 "Updated season data and buff descriptions.": "シーズンデータとバフ説明を更新しました。",
