 "This is one curve point; changing enemy level uses its own point, not this constant.": "これは1つのカーブ上の点です。敵レベルを変えると、この定数ではなくそのレベルの点が使われます。",
 "Defence K · character Lv. 100": "防御K · キャラクターLv. 100",
 "Resistance reduction uses character level independently of the selected Crit enemy level.": "耐性軽減は、選択した会心の敵レベルとは無関係にキャラクターレベルを使います。",
 "CS coefficients in this catalog": "このカタログの戦力係数",
 "B: full base before percentages": "B：割合適用前の完全な基準値",
 "Fixed coefficient per fraction 1.0; 1 percentage point contributes weight / 100.": "割合1.0あたりの固定係数。1パーセントポイントは重み／100に寄与します。",
