 "The coefficient is unknown; this component cannot be calculated.": "係数が不明のため、この項目は計算できません。",
 "Generated from the game attribute weight. Use the curve value at this item’s level before display formatting.": "ゲームの属性ウェイトから生成。表示用の整形前に、このアイテムのレベルにおけるカーブ値を使用してください。",
