 "Slot-specific allowed stat types still apply; the limit does not permit any arbitrary combination.": "スロットごとに許可されるステータス種別は引き続き適用されます。この上限は任意の組み合わせを許可するものではありません。",
 "Upgrade-roll limit": "強化ロール上限",
 "The full forecast uses this limit, while current rating counts the values the item actually has.": "完全予測はこの上限を使い、現在の評価はアイテムが実際に持つ値を数えます。",
 "Observed added-stat share": "観測された追加ステータスの割合",
