 "Why weapon and matrix damage multipliers are separate": "武器とボリションのダメージ倍率が別々に扱われる理由",
 "Q: largest weighted maximum roll after the Titan multiplier, across the generated stat catalog.": "Q：タイタン倍率適用後の、生成されたステータスカタログ全体での重み付き最大ロールの最大値。",
 "Q: largest weighted maximum roll after the Titan multiplier among the stats this role rates.": "Q：タイタン倍率適用後の、このロールが評価するステータスの中での重み付き最大ロールの最大値。",
 "Titan-added stats: why equal rolls can give different HP": "タイタンで追加されるステータス：同じロールでもHPが異なる理由",
 "Equivalent rolls = (primary after Titan − primary initial value) / primary maximum roll": "等価ロール =（タイタン後の主ステータス − 主ステータスの初期値）／ 主ステータスの最大ロール",
 "Added stat = its initial value + observed share × equivalent rolls × its maximum roll": "追加ステータス = 初期値 + 観測された割合 × 等価ロール × そのステータスの最大ロール",
 "enemy-level denominator": "敵レベルの分母",
 "Both Crit weights are zero when c ≥ 1.": "c ≥ 1の場合、両方の会心の重みはゼロです。",
 "Equipped gear": "装備中",
 "Build maximum": "ビルドの最大値",
 "Build roll quality": "ビルドのロール品質",
 "Equip at least one item and provide valid rating inputs for every equipped slot. Empty slots add no points; their ceilings remain part of the build maximum.": "1つ以上のアイテムを装備し、装備中のすべてのスロットに有効な評価入力を入力してください。空のスロットは点数に加算されませんが、その上限はビルドの最大値に含まれます。",
 "Total of the equipped items’ GRV against the total of their slot ceilings, using one reference profile for everyone.": "装備中のアイテムのGRVの合計を、スロット上限の合計と比較したものです。全員が同じ基準プロフィールを使用します。",
 "Total of the equipped items’ PRV against the total of their slot ceilings, using your current panel stats.": "装備中のアイテムのPRVの合計を、スロット上限の合計と比較したものです。現在のパネルのステータスを使用します。",
 "Sum of the slot scores. Open the RV of an item for its own breakdown.": "スロットスコアの合計です。アイテムのRVを開くと、その内訳を確認できます。",
 "Share of the build maximum. It is not a damage bonus or a ranking among players.": "ビルドの最大値に対する割合です。ダメージボーナスやプレイヤー間の順位ではありません。",
 "Each item is rated after removing only that item, so the total is not the effect of removing or adding the whole set at once.": "各アイテムは、そのアイテムだけを取り除いた状態で評価されるため、合計値はセット全体を一度に外した場合や加えた場合の効果ではありません。",
 "Total Global Roll Value": "グローバルロール値の合計",
 "Total Personal Roll Value": "個人ロール値の合計",
 "Total ": "合計 ",
 "Current stats": "現在のステータス",
 "Slot ceiling": "スロット上限",
 "Slot roll quality": "スロットのロール品質",
 "of slot ceiling": "スロット上限に対する割合",
 "Enter base ATK, ATK%, DMG%, Crit and a supported enemy level. Totals must include this equipped item and remain valid after removal.": "基本ATK、ATK%、DMG%、会心、対応する敵レベルを入力してください。合計には、この装備中のアイテムを含め、取り外した後も有効である必要があります。",
 "Enter all four pre-Titan stats.": "タイタン前の4つのステータスをすべて入力してください。",
 "The source does not confirm this pull-up case.": "このプルアップの条件は、ソースでは確認されていません。",
 "Check SSR stat ranges and stars.": "SSRのステータス範囲と星を確認してください。",
 "Tied strongest stats: conservative estimate.": "同率で最も強いステータス：保守的な推定値です。",
 "One reference profile for everyone. Compare tank gear as it is now by the effective HP it adds against the selected element, independently of account stats.": "全員共通の基準プロフィールです。アカウントのステータスとは関係なく、選択した属性に対して現在の装備が追加する有効HPで比較します。",
 "One reference profile for everyone. Compare healer gear as it is now by the ATK it adds, independently of account stats.": "全員共通の基準プロフィールです。アカウントのステータスとは関係なく、現在の装備が追加するATKで比較します。",
 "One reference profile for everyone. Compare offensive gear as it is now in the same element and weapon context, independently of account stats.": "全員共通の基準プロフィールです。アカウントのステータスとは関係なく、同じ属性と武器の条件で、現在の装備を比較します。",
 "The current equipped item is subtracted first. Its current stats are then rated using the remaining build, rather than added on top of its own current stats.": "現在装備中のアイテムは先に差し引かれます。そのうえで、現在のステータスは残りのビルドを使って評価され、自身の現在のステータスに上乗せされるわけではありません。",
 "Share of this slot’s theoretical ceiling, not extra damage or a ranking among players.": "このスロットの理論上の上限に対する割合です。追加のダメージやプレイヤー間の順位ではありません。",
 "Single element": "単一属性",
 "Rated: HP, HP%, general RES, the element’s RES and RES%": "評価対象：HP、HP%、汎用耐性、その属性の耐性と耐性%",
 "Percent-stat pool": "パーセントステータスのプール",
 "no crit or DMG%": "会心およびDMG%はなし",
 "Maximum roll weights": "最大ロールの重み",
 "Build without this item": "このアイテムを除いたビルド",
 "Reference used for this score": "このスコアに使用した基準",
 "Current item removed from the panel totals": "パネル合計から取り除いた現在のアイテム",
 "HP removed": "除外されたHP",
