 "Crit removed": "除外された会心",
 "Crit Rate removed": "除外された会心率",
 "Personal reference unavailable. GRV is available through the switch below the card.": "個人の基準は利用できません。GRVは、カード下のスイッチから利用できます。",
 "These baseline values are site assumptions, not official game constants. Your buffs, enemy level and current Crit do not change GRV weights.": "これらの基準値はサイトの想定値であり、公式のゲーム定数ではありません。お使いのバフ、敵レベル、現在の会心はGRVの重みを変更しません。",
 "How the calculation works": "計算の仕組み",
