 "MMO build card help": "MMOビルドカードのヘルプ",
 "About the MMO card": "MMOカードについて",
 "My MMO builds": "マイMMOビルド",
 "Public MMO builds": "公開MMOビルド",
 "A showcase card of a Warp (MMO) character, filled from your own .tofbuild capture or by hand.": "Warp（MMO）キャラクターのショーケースカードです。ご自身の.tofbuildキャプチャから、または手入力で作成します。",
 "What the import fills": "インポートで読み込まれる内容",
 "Name, UID, level, CS, crew, title, avatar and frame from the login.": "ログインから得られる名前、UID、レベル、CS、クルー、称号、アバター、フレーム。",
 "Attributes and equipment": "属性と装備",
 "The attribute panel, 12 gear slots with their random stats and the expansion card of each slot.": "属性パネル、ランダムステータス付きの12の装備スロット、各スロットの拡張カード。",
 "Three weapons with +N and the weapon mode (Regular / Fixed-damage).": "+Nと武器モード（通常／固定ダメージ）付きの3つの武器。",
 "Node levels; hover a chain for its stat sums.": "ノードのレベル。連鎖にカーソルを合わせるとステータスの合計が表示されます。",
 "Smart Servant and food": "スマートサーバントと料理",
 "The pet with its inherited ATK and the active dishes. An empty slot shows \"Nothing\".": "継承したATKを持つペットと有効な料理。空のスロットには「なし」と表示されます。",
 "Parts the game did not send at this login stay empty and are listed after the import. Open those windows in the game and capture again.": "このログイン時にゲームから送られなかった部分は空のままになり、インポート後に一覧表示されます。そのウィンドウをゲーム内で開き、もう一度キャプチャしてください。",
 "Saving and public builds": "保存と公開ビルド",
 "One build per role": "役割ごとに1つのビルド",
 "Choose DPS, Tank, Healer or Balance at the top right of the card and press \"Save build\". Each role keeps its own public card.": "カードの右上でDPS、タンク、ヒーラー、またはバランスを選び、「ビルドを保存」を押してください。役割ごとに、それぞれ専用の公開カードが保持されます。",
 "Only the unedited import": "編集していないインポートのみ",
 "The site stores the signed capture, so value edits block saving. Role and background are free choices.": "サイトは署名付きのキャプチャを保存するため、値を編集すると保存がブロックされます。役割と背景は自由に選択できます。",
 "Live Warp servers": "稼働中のWarpサーバー",
 "Test-server, DEV-client and unresolved captures are shown but never saved.": "テストサーバー、DEVクライアント、未解決のキャプチャは表示されますが、保存はされません。",
 "MMO has no ranking, Wish Tracker or gear optimizer on the site.": "MMOには、サイトのランキング、Wish Tracker、装備の最適化ツールはありません。",
 "Public MMO builds of this character, one per role. Save the card with \"Save build\" under it.": "このキャラクターの公開MMOビルドです。役割ごとに1つあります。その下の「ビルドを保存」でカードを保存してください。",
 "Import your .tofbuild capture to see this character’s saved MMO builds.": "このキャラクターの保存済みMMOビルドを確認するには、.tofbuildキャプチャをインポートしてください。",
