 "MMO builds": "MMOビルド",
 "Show more": "さらに表示",
 "Saving needs a card imported from a .tofbuild file: import the file from the capture app first.": "保存するには、.tofbuildファイルからインポートしたカードが必要です。まずキャプチャアプリからファイルをインポートしてください。",
 "Test-server, DEV-client and unresolved captures cannot be saved. Viewing and PNG export are available.": "テストサーバー、DEVクライアント、未解決のキャプチャは保存できません。閲覧とPNGのエクスポートは利用できます。",
