 "With inheritance": "継承を含む",
 "Rated stats": "評価されたステータス",
 "Values before Titan and roll counts": "タイタン前の値とロール数",
 "Current values and Titan progress": "現在の値とタイタンの進捗",
 "Verified Titan · own .tofbuild": "検証済みのタイタン · ご自身の.tofbuild",
 "All pieces: verified Titan · own .tofbuild": "すべての装備：検証済みのタイタン · ご自身の.tofbuild",
 "Every piece behind this score is Titan from the player’s own .tofbuild, with known original stats.": "このスコアの対象となるすべての装備は、プレイヤー自身の.tofbuildにあるタイタンで、元のステータスがわかっています。",
 "Titan item from the player’s own .tofbuild, with known original stats. Inspected and non-Titan gear is not verified.": "プレイヤー自身の.tofbuildにあるタイタン装備で、元のステータスがわかっています。確認されていない装備や非タイタンの装備は検証されていません。",
 "Counted stats converted into rating points; 100 = the most valuable single roll at full Titan across all stats.": "カウントされたステータスを評価ポイントに換算したものです。100 = すべてのステータスの中で、タイタンが完全な状態での最も価値のある1回のロールです。",
 "universal ATK, the element’s ATK, ATK % and DMG %, Crit and Crit Rate %; other stats give 0.": "汎用ATK、属性のATK、ATK%、DMG%、会心、会心率%。その他のステータスは0です。",
 "the better flat ATK, ATK % and DMG % of either element of the pair; Crit counts, other stats give 0.": "ペアのどちらかの属性の、固定ATK、ATK%、DMG%のうち高い方。会心はカウントされ、その他のステータスは0です。",
 "The perfect item of the slot: the best legal set of counted stats, every roll on the most valuable one, at full Titan (100 %).": "そのスロットの完璧な装備：カウントされるステータスの最良の有効な組み合わせで、すべてのロールが最も価値の高いものに入り、タイタンが完全な状態（100%）のもの。",
 "Current values of each item. Titan growth is random, so other players’ values before Titan cannot be recovered.": "各装備の現在の値です。タイタンの成長はランダムなため、タイタン前の他のプレイヤーの値は復元できません。",
 "Reference player": "基準プレイヤー",
 "These baseline values are site assumptions, not official game constants; crit uses the game’s crit formula at this enemy level.": "これらの基準値はサイトの想定値であり、公式のゲーム定数ではありません。会心は、この敵レベルにおけるゲームの会心の計算式を使用します。",
 "One reference profile for everyone: each stat is rated by the ATK it adds to the same reference player (crit and DMG % are not rated).": "全員共通の基準プロフィールです。各ステータスは、同じ基準プレイヤーに対して追加されるATKで評価されます（会心とDMG%は評価されません）。",
 "One reference profile for everyone: each stat is rated by the effective HP it adds against the selected element to the same reference tank.": "全員共通の基準プロフィールです。各ステータスは、同じ基準タンクに対して選択した属性に対して追加される実効HPで評価されます。",
 "Counted stats converted into rating points; 100 = the most valuable single roll at full Titan among the stats this role rates.": "カウントされるステータスを評価ポイントに換算したものです。100 = この役割が評価するステータスの中で、タイタンが完全な状態での最も価値のある1回のロールです。",
 "universal ATK, the element’s ATK and ATK %; crit, DMG % and other stats give 0.": "汎用ATK、属性のATK、ATK%。会心、DMG%、その他のステータスは0です。",
 "HP, HP %, general RES (counts like the element’s own), the element’s RES and RES %; other stats give 0.": "HP、HP%、汎用RES（属性自身のRESと同様にカウント）、属性のRES、RES%。その他のステータスは0です。",
 "These baseline values are site assumptions, not official game constants; damage reduction uses the game’s defence formula at this level.": "これらの基準値はサイトの想定値であり、公式のゲーム定数ではありません。ダメージ軽減は、このレベルにおけるゲームの防御の計算式を使用します。",
 "All elements · best element of each server": "すべての属性 · 各サーバーの最適な属性",
 "Added by Titan: this stat did not exist before Titan": "タイタンによって追加：このステータスはタイタン以前には存在しませんでした",
