 "Sum of the twelve slot ceilings (100 % build)": "12のスロット上限の合計（100%のビルド）",
 "Titan growth so far: share of the way from the value before Titan to the full-Titan maximum (Titan-added stats: current value / maximum)": "これまでのタイタンの成長：タイタン前の値から完全なタイタンの最大値までの進捗（タイタンで追加されたステータス：現在の値／最大値）",
