 "On the universal GRV fighter: the reference wearing this row instead of the reference row, everything else equal.": "汎用GRVの戦闘員で：基準行ではなくこの行の装備を付けた基準。他の条件はすべて同じです。",
 "First-order estimate from the GRV totals on the universal fighter (a whole build cannot be swapped into it exactly).": "汎用の戦闘員のGRV合計による一次推定です（ビルド全体を正確に入れ替えることはできません）。",
 "Damage taken relative to health: includes HP and resistance. Lower is better; the ratio is the inverse of effective HP.": "HPに対する受けるダメージ：HPと耐性を含みます。低いほど良く、その比率は実効HPの逆数です。",
