 "Public Global account": "公開のグローバルアカウント",
 "If you need a public account with all Global regions and access to the ranking, you can use these credentials:": "すべてのグローバル地域とランキングへのアクセスを含む公開アカウントが必要な場合は、以下の認証情報を使用できます：",
 "Double-click to select and copy the whole value. Enter or Space also copies.": "ダブルクリックで値全体を選択してコピーできます。EnterまたはSpaceでもコピーされます。",
