 "The API is unavailable or still starting. Retry once it is ready.": "APIは利用できないか、まだ起動中です。準備ができたら再試行してください。",
 "Turn off Verified only or change the filters. Original GRV places are preserved.": "「検証済みのみ」をオフにするか、フィルターを変更してください。元のGRVの順位は保持されます。",
 "Capture your own build": "ご自身のビルドをキャプチャ",
 "Use the capture app on your PC, save your character as .tofbuild and upload the file to update their data.": "PCのキャプチャアプリを使用して、キャラクターを.tofbuildとして保存し、そのファイルをアップロードしてデータを更新してください。",
 "How to collect .tofbuild": ".tofbuildの収集方法",
 "Ask another player": "他のプレイヤーに依頼",
 "Someone else can use the app, open your profile in the game and upload .tofplayers. They do not need access to your account.": "他の人がこのアプリを使えるなら、ゲーム内でご自身のプロフィールを開き、.tofplayersをアップロードしてもらってください。その人がご自身のアカウントにアクセスする必要はありません。",
 "How to collect .tofplayers": ".tofplayersの収集方法",
 "Outdated data or a missing character? There are two ways to update the ranking.": "データが古い、またはキャラクターがない場合は？ランキングを更新する方法は2つあります。",
 "Ways to update": "更新方法",
 "For a fair ranking, only files from the capture app are accepted. Both buttons open the existing app guide with download and upload instructions.": "公平なランキングのため、キャプチャアプリのファイルのみ受け付けます。どちらのボタンも、ダウンロードとアップロードの手順が記載された既存のアプリガイドを開きます。",
