 "ToF | Contribute": "ToF | 貢献",
 "Help keep ToF Hub current by providing a fresh Tower of Fantasy game export for regular Datamine updates, Multype research scans, or manual data corrections.": "定期的なデータマイン更新、Multypeの調査スキャン、または手動でのデータ修正のために、最新のTower of Fantasyゲームのエクスポートを提供して、ToF Hubを最新の状態に保つのにご協力ください。",
