 "Export and unpack the full game": "ゲーム全体をエクスポートして展開",
 "Export the complete game assets to structured JSON using FModel or UnrealExporter with UE_Version set to GAME_TowerOfFantasy.": "FModelまたはUnrealExporterで、UE_VersionをGAME_TowerOfFantasyに設定して、ゲームの全アセットを構造化されたJSONにエクスポートしてください。",
 "Get Tower of Fantasy Exporter Scanner": "Tower of Fantasy Exporter Scannerを入手",
 "Download or clone the scanner Python tool from GitHub:": "GitHubからスキャナーのPythonツールをダウンロードまたはクローンしてください：",
 "Tower of Fantasy Exporter Scanner on GitHub": "GitHubのTower of Fantasy Exporter Scanner",
 "Run the scanner": "スキャナーを実行",
 "Execute the scanner CLI against your JSON export folder to map AttributeName, Modifiers, and ModuleExtraType relationships:": "JSONのエクスポートフォルダーに対してスキャナーCLIを実行し、AttributeName、Modifiers、ModuleExtraTypeの関係をマッピングしてください：",
 "python main_scanning_files.py --input path_to_json --mode 1": "python main_scanning_files.py --input path_to_json --mode 1",
