 "You won the featured pull {{wins}} of {{total}} times ({{rate}}%); the classic baseline is 50.0%.": "注目のガチャに {{total}} 回中 {{wins}} 回勝ちました（{{rate}}%）。従来の基準は50.0%です。",
 "Insufficient data for luck assessment": "運の評価に必要なデータが不足しています",
 "Special Orders Mechanics (Tower of Fantasy)": "特別オーダーの仕組み（Tower of Fantasy）",
 "Rates, hard guarantees, and event order economy. Base odds and the average SSR rate are shown separately.": "確率、確定保証、イベントオーダーの経済。基本確率と平均のSSR率は別々に表示しています。",
 "Rates & guarantees": "確率と保証",
 "The base rate applies to an individual pull before a guarantee triggers.": "基本確率は、保証が発動する前の1回のガチャに適用されます。",
 "Limited orders": "限定オーダー",
 "Weapon banner": "武器バナー",
 "Matrix banner": "ボリションバナー",
 "Base SSR rate": "基本のSSR確率",
 "Base SR rate": "基本のSR確率",
 "Hard SSR guarantee": "確定のSSR保証",
 "Average rate with guarantee": "保証を含む平均確率",
 "pull in each cycle: #{{count}}": "各サイクルのガチャ：#{{count}}",
 "An SSR can drop early, but the fixed cycle still awards an SSR on pull 80.": "SSRは早く出ることもありますが、固定のサイクルでは80回目のガチャで必ずSSRが付与されます。",
 "An SSR matrix can drop early, but the fixed cycle still awards an SSR on pull 40.": "SSRのボリションは早く出ることもありますが、固定のサイクルでは40回目のガチャで必ずSSRが付与されます。",
 "About the average rate:": "平均確率について：",
 "2.00% for weapons and 4.20% for matrices are average SSR rates after accounting for the hard guarantee. They are not the chance on every individual pull.": "武器の2.00%とボリションの4.20%は、確定の保証を含めた平均のSSR率です。個々のガチャごとの確率ではありません。",
 "How pity works": "天井の仕組み",
 "SSR and SR protection.": "SSRとSRの保護。",
 "An SSR is guaranteed on weapon pull 80 or matrix pull 40. Also, if no SR or SSR appears for {{srPity}} pulls, the next pull guarantees SR or higher.": "武器のガチャの80回目またはボリションのガチャの40回目で、SSRが確定します。また、{{srPity}} 回のガチャでSRまたはSSRが出なかった場合、次のガチャでSR以上が確定します。",
 "Pity carries over.": "天井は引き継がれます。",
 "Limited weapon pity carries between weapon event banners; matrix pity carries between matrix event banners. The two tracks are independent.": "限定武器の天井は武器のイベントバナー間で引き継がれ、ボリションの天井はボリションのイベントバナー間で引き継がれます。2つのトラックは独立しています。",
 "Separate guarantees.": "別々の保証。",
 "The rarity guarantee (SSR) and the featured-item result (50/50) are separate events. A win or loss does not change rarity pity.": "レア度の保証（SSR）と注目アイテムの結果（50/50）は別々のイベントです。勝ちや負けはレア度の天井を変えません。",
 "Early SSR.": "早期のSSR。",
 "An early drop does not reset the fixed guarantee cycle. For example, an SSR on pull 23 does not cancel the next guaranteed SSR on pull 80.": "早期の排出では、確定の保証サイクルはリセットされません。例えば、23回目のガチャでSSRが出ても、80回目の確定SSRはキャンセルされません。",
 "Featured item: 50/50": "注目アイテム：50/50",
 "Standard SSR": "標準SSR",
 "next SSR is standard": "次のSSRは標準です",
 "next SSR is featured": "次のSSRは注目です",
 "standard 50/50 odds": "標準の50/50の確率",
 "Matrix slots": "ボリションのスロット",
 "Currencies & shop": "通貨とショップ",
 "Weapons — Flame Gold.": "武器 — 炎の金。",
 "{{base}} per pull; a maxed SR duplicate grants +{{srBonus}}, and a maxed standard SSR duplicate grants +{{ssrBonus}} more.": "ガチャ1回につき {{base}}。上限に達したSRの重複で +{{srBonus}}、上限に達した標準SSRの重複でさらに +{{ssrBonus}} が付与されます。",
 "Matrices — Overclocking Chips.": "ボリション — オーバークロックチップ。",
 "{{base}} chip per pull; matrix duplicates do not grant extra currency.": "ガチャ1回につきチップ {{base}}。ボリションの重複では追加の通貨は付与されません。",
 "Shop exchange.": "ショップでの交換。",
 "In short:": "要約：",
 "Fixed Rarity Guarantee (80 Weapon / 40 Matrix)": "固定のレア度保証（武器80 / ボリション40）",
 "The counter never resets on early SSR drops! If you get an SSR at pull 23, pull 80 will still grant you a guaranteed SSR.": "早期のSSR排出でカウンターはリセットされません！23回目のガチャでSSRが出ても、80回目のガチャで保証されたSSRが付与されます。",
 "Hidden 50/50 Outcome Mechanics (Streaks)": "隠された50/50の結果の仕組み（連続）",
 "Cashback & Duplicate Compensation": "キャッシュバックと重複の補償",
