 "Base Chip": "基本チップ",
 "→ 1x Bat. II": "→ ウェポンバッテリーII ×1",
 "Converted to Weapon Battery II (Exp Ore)": "ウェポンバッテリーII（Exp Ore）に変換",
 "Extra duplicate cashback: +{{amount}} Flame Gold": "重複の追加キャッシュバック：+{{amount}} 炎の金",
 "Extra duplicate cashback: +{{amount}} Overclocking Chips": "重複の追加キャッシュバック：+{{amount}} オーバークロックチップ",
