 "Global Wish Tally": "グローバルのウィッシュ集計",
 "Community-aggregated Special Orders analytics for Tower of Fantasy: 80/40 non-resetting pity audit, 50/50 rates, and pull distribution": "Tower of Fantasyの特別オーダーの分析をコミュニティで集計：リセットされない80/40の天井の監査、50/50の確率、排出の分布",
