 "Cross-banner comparison of total wishes, drop rates, average pity, and 50/50 win rates": "ウィッシュの合計、排出率、平均天井、50/50の勝率をバナー間で比較",
 "View Tally": "集計を表示",
 "Back to My Wishes": "マイウィッシュに戻る",
 "You can help update the site’s game data. It takes about 30 minutes and requires an installed PC copy of Tower of Fantasy.": "サイトのゲームデータの更新にご協力いただけます。約30分かかり、PC版のTower of Fantasyがインストールされている必要があります。",
 "No changelog entries match the selected filter.": "選択したフィルターに一致する変更履歴はありません。",
 "~2 h": "約2時間",
 "Please select a pack from the catalog on the right": "右のカタログからパックを選択してください",
 "ToF resources": "ToFのリソース",
 "ToF Hub Capture · Windows app": "ToF Hub Capture · Windowsアプリ",
 "Collect your build card and pull history": "ビルドカードとガチャ履歴を収集",
 "The app uses WinDivert to read copies of the game’s TCP/UDP packets on your PC. It collects your build card and pull history from that data.": "このアプリはWinDivertを使用して、PC上のゲームのTCP/UDPパケットのコピーを読み取ります。そのデータからビルドカードとガチャ履歴を収集します。",
 "Download for Windows": "Windows用をダウンロード",
 "Download link coming soon": "ダウンロードリンクは近日公開",
 "Windows 10/11 · 64-bit · administrator rights for the network driver": "Windows 10/11 · 64ビット · ネットワークドライバーには管理者権限が必要",
 "In short": "要点",
 "Get the app above and run it as administrator.": "上からアプリを取得し、管理者として実行してください。",
 "Start before you log in": "ログインの前に開始",
 "Press Start, then log into your character in Hykros. If you are elsewhere, teleport to Hykros and log into your character again.": "開始を押してから、Hykrosでキャラクターにログインしてください。別の場所にいる場合は、Hykrosにテレポートしてから、もう一度キャラクターにログインしてください。",
 "Open two windows": "2つのウィンドウを開く",
 "Upload the file": "ファイルをアップロード",
 "Save .tofbuild and/or .tofwish and upload them here: Tools → Build, Tools → Wish.": ".tofbuildと／または.tofwishを保存して、ここにアップロードしてください：ツール → ビルド、ツール → ウィッシュ。",
 "Safe by design: it only watches, never touches": "設計上安全：監視のみで、何も変更しません",
 "Read-only copy of traffic": "トラフィックの読み取り専用コピー",
 "No game memory access or file changes": "ゲームのメモリへのアクセスやファイルの変更はありません",
 "Sends nothing anywhere": "どこにも送信しません",
 "How it works": "仕組み",
 "Reads a copy of the traffic.": "トラフィックのコピーを読み取ります。",
 "Only the game’s connections.": "ゲームの接続のみ。",
 "Decoded on your PC.": "PC上でデコードされます。",
 "Sealed files.": "封印されたファイル。",
 "No network access of its own.": "独自のネットワークアクセスはありません。",
 "The app makes no requests: no account, no telemetry, no auto-update. You decide which file to upload.": "アプリはリクエストを行いません：アカウント、テレメトリー、自動アップデートはありません。どのファイルをアップロードするかはご自身で決めます。",
 "What the app never touches": "アプリが決して触れないもの",
 "The game.": "ゲーム。",
 "Nothing is injected into the game process, game files are not changed, no proxy, certificate or hook is installed.": "ゲームのプロセスには何も注入されず、ゲームのファイルは変更されず、プロキシ、証明書、フックはインストールされません。",
 "Your accounts.": "お使いのアカウント。",
 "Passwords and login tokens never reach the saved file, and the app removes all of its working files itself when it closes.": "パスワードとログイントークンは保存されたファイルに含まれることはなく、アプリは閉じるときに作業用のファイルをすべて自分で削除します。",
 "Your files.": "お使いのファイル。",
 "What the saved file contains": "保存されたファイルの内容",
 "Character name, UID and RoleId, level, crew, title, signature": "キャラクター名、UIDとRoleId、レベル、クルー、称号、署名",
 "Optional: PWG UID from the matching in-game top-up link in HottaBrowser.log; stored under the game UID after import": "任意：HottaBrowser.logにある、対応するゲーム内のチャージリンクのPWG UID。インポート後にゲームのUIDの下に保存されます。",
 "Combat stats, weapons, matrices, gear with pre-Titan values and Titan clicks, pet, relics, Supercomputing, Space Support": "戦闘ステータス、武器、ボリション、タイタン前の値とタイタンのクリックを含む装備、ペット、アルケー、スーパーコンピューティング、宇宙支援",
 "Special Order history: banner, time and item of every pull (.tofwish)": "特別オーダーの履歴：各ガチャのバナー、時刻、アイテム（.tofwish）",
 "Passwords, login tokens and payment details (card numbers, purchases)": "パスワード、ログイントークン、支払いの詳細（カード番号、購入）",
 "Chat, friends, mail": "チャット、フレンド、メール",
 "Anything from other programs or your files": "他のプログラムやお使いのファイルからのもの",
 "Never saved": "保存されることはありません",
