 "Base stats.": "基本ステータス。",
 "Ranges.": "範囲。",
 "Totals.": "合計。",
 "Average at 5 rolls = base + 5 × (min + max) / 2; maximum = base + 5 × max. The Gold rows are checked against the reference Stat ranges table on every run.": "5ロールでの平均 = 基本値 + 5 ×（最小 + 最大）／ 2、最大値 = 基本値 + 5 × 最大。ゴールドの行は、実行のたびに基準のステータス範囲の表と照合されます。",
 "Chances by slot.": "スロット別の確率。",
 "Each item names its pool (EquipmentDataTable → RandomModifyData). One draw uses positive weights; -1 marks a guaranteed stat.": "各アイテムはそのプールを示します（EquipmentDataTable → RandomModifyData）。1回の抽選は正の重みを使用し、-1は確定のステータスを示します。",
 "Whole-item model.": "アイテム全体のモデル。",
 "Rare properties.": "レア特性。",
 "EquipUncommonModifyData: each entry becomes available once the augmentation count reaches TupoCountLimited; chance = Weight / sum of available weights.": "EquipUncommonModifyData：各エントリは、強化回数がTupoCountLimitedに達すると利用可能になります。確率 = 重み ÷ 利用可能な重みの合計。",
 "Roll chance.": "ロールの確率。",
 "EquipUncommonRateData.UncommonRate per augmentation-count row; counts between rows are not confirmed.": "強化回数の行ごとのEquipUncommonRateData.UncommonRate。行の間の回数は確認されていません。",
 "Main-stat growth.": "主要ステータスの成長。",
 "EquipRandomModifyData.TupoAddABSValueMap: five weighted bands per count; expected value assumes a uniform value inside a band.": "EquipRandomModifyData.TupoAddABSValueMap：回数ごとに5つの重み付きの帯。期待値は、帯の内部で値が一様であると仮定します。",
 "Added stats.": "追加されたステータス。",
 "The ideal rule derived from captured items and used on the Tools pages (build-reference titanGrowth).": "キャプチャしたアイテムから導出され、ツールのページで使用される理想のルール（build-reference titanGrowth）。",
 "Weights.": "重み。",
 "AttributeStaticDataTable weight of every attribute, as used by the Build card CS rules.": "ビルドカードのCSのルールで使用される、すべての属性のAttributeStaticDataTableの重み。",
 "Other systems.": "その他のシステム。",
 "Cost.": "コスト。",
 "EquipStrengthenDataTable row N is the price of reaching +N (NeedItems, NeedGolds); a range is the sum of its rows.": "EquipStrengthenDataTableの行Nは+Nに到達するための価格です（NeedItems、NeedGolds）。範囲は、その行の合計です。",
 "Main stats.": "主要ステータス。",
 "Base stats plus EquipStrengthenEffectPack growth and the stats unlocked every five levels, truncated like in the game.": "基本ステータスに、EquipStrengthenEffectPackの成長と5レベルごとに解放されるステータスを加えたもの。ゲームと同様に切り捨てられます。",
 "Success chance.": "成功の確率。",
 "Clicks.": "クリック。",
 "EquipSlotEvolution tables: experience per level, click outcomes with weights and eligible experience ranges; expected clicks assume excess experience is lost.": "EquipSlotEvolutionのテーブル：レベルごとの経験値、重み付きのクリックの結果と対象となる経験値の範囲。期待されるクリック数は、余分な経験値が失われると仮定します。",
 "Versions.": "バージョン。",
 "MMO combat buffs.": "MMOの戦闘バフ。",
 "Node and skill data.": "ノードとスキルのデータ。",
 "Graph.": "グラフ。",
 "Display values.": "表示される値。",
 "Special effects.": "特殊効果。",
 "BuffObject and the localized descriptions are linked per level. Custom event behavior, stacking, and season gating are not computed from the buff assets.": "BuffObjectとローカライズされた説明はレベルごとにリンクされています。カスタムイベントの挙動、重ね掛け、シーズンの制限はバフのアセットからは計算されません。",
 "Costs.": "コスト。",
 "System levels.": "システムのレベル。",
 "Crit.": "会心。",
 "CritFormula curves give the denominator D for each enemy level; chance = Crit / D.": "CritFormulaの曲線は、各敵レベルの分母Dを与えます。確率 = 会心 ÷ D。",
 "Resistance.": "耐性。",
 "DefenceFormula curves give K for each level; reduction = RES / (RES + K). Ignore and shred follow the documented community model.": "DefenceFormulaの曲線は、各レベルのKを与えます。軽減 = RES ÷（RES + K）。無視と貫通は、文書化されたコミュニティのモデルに従います。",
 "Servers.": "サーバー。",
 "The official server list the PC launcher downloads, plus China and Taiwan snapshots; the first digits of a UID are the server ID.": "PCのランチャーがダウンロードする公式のサーバー一覧と、中国および台湾のスナップショット。UIDの最初の桁はサーバーIDです。",
