 "A row is a triple: its module context (": "この行は3つ組です：そのモジュールの文脈（",
 "), its attribute / sub-table (e.g. ": "）、その属性／サブテーブル（例：",
 "), and the source buff file. That raw triple is the ": "）、および元のバフファイル。この生の3つ組が",
 " view.": "ビューです。",
 "Then, using the in-game console, each buff is pulled live and its real effect is verified, and a human-readable name is attached. That verified name is the ": "その後、ゲーム内のコンソールで各バフをライブで取得し、実際の効果を検証して、人が読める名前を付けます。その検証済みの名前が",
 "Combined": "結合",
 "Each table (module × attribute) is its own multiplier bucket. Values ": "各テーブル（モジュール × 属性）は、それぞれ独自の倍率のグループです。値は",
 " one table add together; ": "1つのテーブル内で合算され、",
 "The critical point: two tables can show the ": "重要な点：2つのテーブルは、同じ表示名（「Final Dmg」）を示す場合でも、",
 " display name (“Final Dmg”) and still be ": "表示名",
 " categories, because they live under different modules. In game they ": "カテゴリであり、異なるモジュールに属しています。ゲーム内では、",
 " even though the label looks identical. The same is true for the elemental tables (Ice / Fire / Volt / Phys attack).": "ラベルが同じに見えても、それぞれ乗算されます。属性のテーブル（氷／炎／雷／物理の攻撃）も同様です。",
 "Multiplied": "乗算されます",
 "Almost everything you care about is Final Dmg plus the Elemental Dmg of your element. These split into a few ": "あなたが重視するほぼすべては、Final Dmgと、あなたの属性のElemental Dmgです。これらは数個の",
 "main groups": "主要グループ",
 " cross. To compare matrices you do ": "を横断します。ボリションを比較するには、",
 " need to think about which weapons you run: matrices synergize among themselves by the simple Final Dmg + Elemental Dmg rule and never overlap with weapons. ": "使用する武器について考える必要はありません。ボリションは、単純なFinal Dmg + Elemental Dmgのルールによって互いに相乗効果を生み、武器と重なることはありません。",
 " and you will be exactly right.": "そうすれば、正確に理解できます。",
 "If the buff is granted on a skill press / some action, it is ": "バフがスキルの発動や何らかの行動によって付与される場合は、",
 "ACTIVE": "ACTIVE",
 " (compare among actives).": "（アクティブ同士で比較します）。",
 "If the buff is granted simply for the weapon existing in your build, it is ": "バフがビルドに武器が存在するだけで付与される場合は、",
 "PASSIVE": "PASSIVE",
 "Relics: Final and Elemental are counted separately, and relics do ": "アルケー：FinalとElementalは別々に数えられ、アルケーは",
 " combine with traits or matrices.": "特性やボリションと組み合わさります。",
 "Those specific relics are ": "それらの特定のアルケーは",
 " bound by the group rules above. Relics appearing in ": "上記のグループのルールに従います。アルケーに現れる",
 "In the end, all resulting combat damage in your build scales as the product of two fundamental multiplier blocks: ": "最終的に、ビルドにおけるすべての戦闘ダメージは、2つの基本的な倍率ブロックの積としてスケールします：",
 "Final Dmg × Elemental Dmg": "Final Dmg × Elemental Dmg",
 "In turn, each of these two blocks is multiplied across its own independent categories: ": "さらに、これら2つのブロックはそれぞれ、独立した独自のカテゴリにまたがって乗算されます：",
 " from matrices multiplies by ": "ボリション由来の値は",
 " from active weapon buffs, by ": "アクティブな武器バフ由来の値と掛け合わされ、",
 " from passive weapon buffs, traits, and relics. In the exact same way, ": "パッシブな武器バフ、特性、アルケー由来の値とも掛け合わされます。同様に、",
 " multiplies across matrices, weapon active, weapon passive, traits, and relics.": "Elemental Dmgの値は、ボリション、武器のアクティブ、武器のパッシブ、特性、アルケーに対して乗算されます。",
 "Total Multiplier = Final Dmg × Elemental Dmg": "総倍率 = Final Dmg × Elemental Dmg",
 "• Final Dmg: Matrix × Weapon Active × Weapon Passive × Traits × Relics": "• Final Dmg：ボリション × 武器アクティブ × 武器パッシブ × 特性 × アルケー",
 "• Elemental Dmg: Matrix × Weapon Active × Weapon Passive × Traits × Relics": "• Elemental Dmg：ボリション × 武器アクティブ × 武器パッシブ × 特性 × アルケー",
 "Frost Dmg and Elemental Dmg are one and the same thing": "Frost DmgとElemental Dmgは、まったく同じものです",
 "If one buff says ": "あるバフが",
 "\"Frost Dmg +X%\"": "「Frost Dmg +X%」",
 " and another says ": "と言い、別のバフが",
 "\"Elemental Dmg +Y%\"": "「Elemental Dmg +Y%」",
 "Drone": "Drone",
 "Instead of placing Lan's simulacrum trait into character traits, the developers placed it directly into the Matrix module (": "開発者は、Lanのアバター特性をキャラクターの特性に入れる代わりに、ボリションのモジュール（",
 ", there was already an established sub-table ": "）に直接入れてしまいました。すでに確立されたサブテーブル",
 "ThunderAtkExtraUpMult": "ThunderAtkExtraUpMult",
 " (31 files). However, developers arbitrarily added a 'Be' prefix — ": "（31ファイル）がありました。しかし開発者は、根拠なく 'Be' の接頭辞を追加し、",
 " (2 files) — and shoved new buffs there without any apparent logical rationale, creating an unintentional separate multiplier:": "（2ファイル）、その中に新しいバフを、意図しない別個の倍率を生み出す形で詰め込みました：",
