 "ToF | Multype Guide": "ToF | Multype ガイド",
 "Player guide to Tower of Fantasy buff stacking, multiplier categories, and ModuleExtraType in the Multype tool.": "Multypeツールにおける、Tower of Fantasyのバフの重ね掛け、倍率のカテゴリ、ModuleExtraTypeについてのプレイヤー向けガイドです。",
 "MULTYPE GUIDE": "MULTYPEガイド",
 "Buff Stacking & Multipliers": "バフの重ね掛けと倍率",
 "A player-facing reference on how buff effects stack, which categories multiply, and how to read the Multype data tables.": "バフ効果がどのように重ね掛けされ、どのカテゴリが乗算されるか、そしてMultypeのデータテーブルの読み方について、プレイヤー向けに解説したリファレンスです。",
 "Back to Multype page": "Multypeページに戻る",
 "ON THIS PAGE": "このページの内容",
 "How the renaming is built": "名称変更の仕組み",
 "Reading it properly": "正しい読み方",
 "Simplified reading": "簡易的な読み方",
 "These readable names are not hand-typed from guides. The whole game export was scanned; every modifier structure found in the assets becomes a raw row in the dataset.": "これらの読みやすい名前は、ガイドから手入力したものではありません。ゲームのエクスポート全体がスキャンされ、アセット内で見つかったすべての修飾子の構造が、データセットの生の行になります。",
 "Raw triple (Datamined view):": "生の3つ組（データマインのビュー）：",
 "Verified readable name (Renamed view):": "検証済みの読みやすい名前（名称変更のビュー）：",
 "Reading it properly: different tables = different buffs": "正しい読み方：テーブルが異なれば、バフも異なる",
 "REAL ILLUSTRATION": "実例",
 "Ene A6 10% in two different tables": "Ene A6 10%：2つの異なるテーブルにある場合",
 "The exact same buff file appears in two different tables simultaneously. Because these tables are separate multiplier buckets, both bonuses apply and multiply:": "まったく同じバフファイルが、2つの異なるテーブルに同時に現れます。これらのテーブルは別々の倍率のグループであるため、両方のボーナスが適用され、乗算されます：",
 "Table 1 (Frost Debuff)": "テーブル1（氷のデバフ）",
 "Frost damage debuff (+10%)": "氷ダメージのデバフ（+10%）",
 "Table 2 (Final Dmg Debuff)": "テーブル2（Final Dmgのデバフ）",
 "Final damage taken debuff (+10%)": "受けるFinalダメージのデバフ（+10%）",
 "In-game result: (1 + 0.10) × (1 + 0.10) = 1.21× multiplier (Multiplicative, not additive 1.20×)": "ゲーム内の結果：(1 + 0.10) × (1 + 0.10) = 1.21倍（加算の1.20倍ではなく、乗算）",
 "If searching for every buff across complex categories without developer console access feels too demanding, use the simplified template below — it covers 99% of all build and stacking questions (provided the game developers haven't made an anomaly in the data itself).": "開発者コンソールにアクセスせずに、複雑なカテゴリにわたるすべてのバフを調べるのが大変な場合は、以下の簡易テンプレートを使用してください。ゲームのデータ自体に開発者による異常がない限り、ビルドと重ね掛けに関するほぼすべての質問に対応します。",
 "Go to Simplified reading": "簡易的な読み方へ",
